import {mealPhoto} from './meal-photos.js';
import {createAiUI} from './ai-ui.js';
import {foodPreferences,dietFits} from './diets.js';
import {pairingConnection,voteFit} from './planning.js';
import {eveningTimeline,featuredEvenings} from './evening.js';
import {movieNights,movieNightById} from './movie-nights.js';
import {artworkFor,tmdbImage} from './artwork.js';
import QRCode from 'qrcode';
import {meals,shows,moods,defaults,mealById,showById,registerShows,mealCategories,filterMeals,mealCuisines} from './catalog.js';
import {recommend,ingredients,recipeSteps,selectedWatchPrefs} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#app');
let rescueDraft=null;
const aiUI=createAiUI({api,go,render,toast,get:()=>({household,draft,night}),refresh:async()=>{household=await api('household');},pin:()=>draft.mode==='watch'?{showId:draft.sourceId}:{mealId:draft.sourceId},select:(p,prefs)=>{registerShows([p.show]);draft={mode:'watch',sourceId:p.show.id,externalShow:p.show,prefs,pair:{mealId:p.meal.id,showId:p.show.id},adapted:false,confirmed:[...household.pantry],ai:{reason:p.reason,ritual:p.ritual,tradeoff:p.tradeoff}};persist();go('review');},rescue:async(r,index)=>{night=await api('nights/'+r.nightId);rescueDraft={...r,choice:r.options[index],adapted:false};rescueReview();}});

let mealCategory='All recipes',mealTime=60,mealCuisine='Any cuisine',recipeLimit=24,themeLimit=20,themeSearch='';
let household=null,key='',busy=false,night=null,shareLink='',search='',savedFilter='all',polling=false;
const sharedKey=new URLSearchParams(location.search).get('cook');
let draft={mode:'meal',sourceId:'mushroom-toast',prefs:{...defaults},pair:null,adapted:false,confirmed:[]};
try{key=localStorage.getItem('supper-household')||'';const saved=JSON.parse(sessionStorage.getItem('supper-draft')||'null');if(saved?.prefs&&['meal','watch'].includes(saved.mode))draft={...draft,...saved};}catch{}
draft.prefs.catalog='Real titles';
let feedback={meal:'again',pairing:'great',shorter:false,rememberMood:true};
const img=(name)=>'/app/images/'+name+'.png';
const watchImg=s=>artworkFor(s)?.image||img(s.scene);
const artClass=s=>artworkFor(s)?'title-art':'';
const artAlt=s=>s.name+(artworkFor(s)?' — promotional artwork':' — illustrative atmosphere');
const route=()=>sharedKey?'phone':(location.hash.slice(1)||'home').split('/')[0];
const routeId=()=>location.hash.slice(1).split('/')[1];
function persist(){try{sessionStorage.setItem('supper-draft',JSON.stringify(draft));}catch{}}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function api(path,method='GET',data){const response=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json',...(key?{'x-household-key':key}:{})},...(data?{body:JSON.stringify(data)}:{})});let result;try{result=await response.json();}catch{throw Error('The server is unavailable. Please try again.');}if(!response.ok)throw Error(result.error||'Something went wrong. Please try again.');return result;}
async function load(){try{if(sharedKey){night=await api('shared/'+sharedKey);render();try{night=await api('shared/'+sharedKey+'/connect','POST',{});render();}catch{toast('Recipe opened. TV confirmation will be available after reconnecting.');}return;}if(key){household=await api('household');}else{const result=await api('household','POST');key=result.key;localStorage.setItem('supper-household',key);household=result;}if(!sessionStorage.getItem('supper-draft'))draft.prefs={...household.prefs,catalog:'Real titles'};await loadRoute();}catch(e){app.innerHTML=`<main class="error-state"><img src="/app/images/crave-frame-3d-v5.png" width="56" alt=""><h1>Let’s get your evening ready.</h1><p>${esc(e.message)}</p><button class="btn primary" data-action="retry">Try again</button><a class="btn" href="/">Open Crave Frame</a></main>`;}}
async function loadRoute(){const r=route();if(['saved','home','kitchen'].includes(r)&&household)household=await api('household');if(['tonight','cook','feedback'].includes(r)){try{night=await api('nights/'+routeId());if(r==='feedback')feedback=night.feedback||{meal:'again',pairing:'great',shorter:!!household.memory.shorter,rememberMood:true};}catch(e){toast(e.message);go('saved');return;}}render();}
function button(label,action,extra='',cls=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function badge(text,cls=''){return `<span class="badge ${cls}">${esc(text)}</span>`;}
function chips(field,options,current){return `<div class="chips" role="group" aria-label="${field}">${options.map(([value,label])=>`<button class="chip ${String(current)===String(value)?'selected':''}" data-action="pref" data-field="${field}" data-value="${value}" aria-pressed="${String(current)===String(value)}">${label}</button>`).join('')}</div>`;}
function header(){const r=route();return `<header class="topbar"><a class="brand" href="#home"><img src="/app/images/crave-frame-3d-v5.png" alt="">Crave Frame</a><nav aria-label="Main navigation"><a class="${r==='concierge'?'active':''}" href="#concierge">✦ Concierge</a><a class="${['home','choose','preferences','results','review'].includes(r)?'active':''}" href="#home">Discover</a><a class="${r==='movie-nights'?'active':''}" href="#movie-nights">Movie nights</a><a class="${r==='kitchen'?'active':''}" href="#kitchen">My kitchen</a><a class="${r==='saved'?'active':''}" href="#saved">Saved nights${household?.nights.length?` <span class="nav-count">${household.nights.length}</span>`:''}</a></nav><button class="avatar" data-action="about" aria-label="About your household">${draft.prefs.people===1?'1':'2+'}</button></header>`;}
function footer(){return `<footer class="app-footer"><span>Your night, well paired.</span><div><button data-action="about">About Crave Frame</button><a href="#kitchen">Your preferences</a><span class="remote-hint">Arrow keys to explore · Enter to select</span></div></footer>`;}
function steps(active){return `<div class="stepper" aria-label="Planning progress">${['Choose','Your evening','Pairings','Make it yours'].map((s,i)=>`<span class="${i===active?'current':i<active?'done':''}"><b>${i<active?'✓':i+1}</b>${s}</span>`).join('')}</div>`;}
function title(kicker,heading,description='',back='home'){return `<div class="page-heading"><button class="back" data-action="go" data-to="${back}" aria-label="Go back">← Back</button><p class="eyebrow">${kicker}</p><h1>${heading}</h1>${description?`<p class="lead">${description}</p>`:''}</div>`;}
function mealCard(m,action='choose',selected=false){return `<button class="food-card ${selected?'chosen':''}" data-action="${action}" data-id="${m.id}"><div class="food-image"><img src="${mealPhoto(m)}" alt="${esc(m.name)}" loading="lazy"><span class="image-badge">${m.minutes} min</span></div><div class="card-body"><h3>${m.name}</h3><p>${m.subtitle}</p><div class="meta"><span>Serves ${draft.prefs.people}</span><span>${m.effort}</span><span>${esc(m.category||'Recipe')}</span><span>${m.foodType||'Vegetarian · plant-based option'}</span></div></div></button>`;}
function showCard(s,action='choose'){return `<button class="show-card" data-action="${action}" data-id="${s.id}"><div class="poster ${s.scene} ${artClass(s)}"><img src="${watchImg(s)}" alt="${esc(artAlt(s))}" loading="lazy"><span class="image-badge">${s.kind}</span><div><span class="eyebrow">${esc(s.genre)}</span><h3>${esc(s.name)}</h3></div></div><div class="card-body"><div class="meta"><span>${esc(s.minutes)} min</span><span>${s.mood}</span><span>${s.source?esc(s.rating):s.custom?'Your title':'Fictional title'}</span></div><p>${esc(s.description)}</p></div></button>`;}
function home(){const latest=household.nights.find(n=>n.status!=='complete');return `${aiUI.home()}<section class="home-hero" style="--hero:url('${img('toast')}')"><div class="hero-copy"><p class="eyebrow">Your next great night in</p><h1>Dinner decided.<br>Evening sorted.</h1><p class="lead">Choose a meal or something to watch.<br>Plan, cook, and enjoy your evening together.</p><div class="hero-detail">${artworkFor(showById('grand-budapest'))?`<img class="hero-title-image" src="${watchImg(showById('grand-budapest'))}" alt="The Grand Budapest Hotel promotional artwork">`:''}<span>Inspired by the evening</span><p>The Grand Budapest Hotel · Comedy drama · 99 min</p><p class="dish-line">Mushroom toast & crispy potatoes</p></div><div class="actions">${button('Start with supper <span>→</span>','start','data-mode="meal"','primary')}${button('Start with a watch <span>→</span>','start','data-mode="watch"')}</div></div></section>${latest?`<div class="resume-bar"><div><span class="eyebrow">Your evening is waiting</span><p>${esc(mealById(latest.mealId).name)} + ${esc(showById(latest.showId).name)}</p></div>${button('Continue your night →','go',`data-to="tonight/${latest.id}"`)}</div>`:''}${household.memory.shorter?`<div class="memory-note"><span>✦</span><div><strong>A little more you.</strong><p>Your saved preference favors cozy episodes under 45 minutes. You’ll see it reflected in your next pairings.</p></div><a href="#kitchen">Edit memory →</a></div>`:''}<div class="section-heading"><div><p class="eyebrow">Set the scene</p><h2>What kind of night?</h2></div><span class="muted">Two ways in. One great evening.</span></div><div class="mood-grid">${moods.map((m,i)=>`<button class="mood-tile" style="--scene:url('${img(['manor','coast','lake','coast'][i])}')" data-action="mood-start" data-mood="${m}"><span>${['Cozy mystery','Something lighthearted','Family adventure','Date night'][i]}</span><span>↗</span></button>`).join('')}</div><div class="section-heading"><div><p class="eyebrow">From your kitchen</p><h2>Good food. A good place to start.</h2></div>${button('Explore '+meals.length+' meals →','start','data-mode="meal"','text-btn')}</div><div class="cards">${meals.filter(m=>['recipe-smoky-black-bean-tacos','recipe-coconut-chickpea-and-spinach-curry','recipe-sesame-broccoli-noodles'].includes(m.id)).map(m=>mealCard(m,'quick-meal')).join('')}</div>${featuredSection()}<div class="demo-invite"><div><h2>Your next evening starts here.</h2><p>A cozy mystery, mushroom toast, and a shorter watch next time.</p></div>${button('Plan a cozy evening →','demo','','primary')}</div>`;}
function featuredSection(){return '<section class="featured-evenings"><div class="section-heading"><div><p class="eyebrow">Find your next night in</p><h2>A great night starts here.</h2></div></div><div class="cards">'+featuredEvenings.map(d=>{const show=showById(d.showId),meal=mealById(d.mealId);return '<article class="saved-card"><img class="feature-poster" src="'+watchImg(show)+'" alt="'+esc(show.name)+' promotional artwork"><div class="card-body"><p class="eyebrow">'+(d.mode==='meal'?'Supper → screen':'Screen → supper')+'</p><h3>'+d.title+'</h3><p>'+esc(show.name)+' · '+show.minutes+' min</p><p><strong>'+meal.name+'</strong></p><p>'+d.reason+'</p>'+button('Try this evening →','featured','data-id="'+d.id+'"','primary full')+'</div></article>';}).join('')+'</div><p class="catalog-note">Choose preferences → compare three pairings → approve an adaptation → cook on your phone → save feedback and see what changes.</p></section>';}
function timelinePanel(n){const meal=mealById(n.mealId),show=n.show||showById(n.showId),rows=eveningTimeline(n,meal,show),format=t=>new Date(t).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}),date=new Date(rows[0].at).toLocaleDateString([],{month:'short',day:'numeric'});return '<section class="evening-schedule panel"><p class="eyebrow">Tonight’s timeline · '+date+'</p><h2>Make room for the whole evening.</h2><div class="schedule-grid">'+rows.map((r,i)=>'<div><span class="schedule-dot">'+(i+1)+'</span><strong>'+format(r.at)+'</strong><p>'+r.label+'</p><small>'+(r.minutes?r.minutes+' min':'Time to unwind')+'</small></div>').join('')+'</div><p class="catalog-note">Planning estimates: prep is included in recipe time. Allow extra time for unfamiliar recipes. Times display in this device’s time zone.'+(n.watchStarted?' Viewing reflects your actual start time.':'')+'</p>'+(!sharedKey?'<details><summary>Adjust the evening</summary><label class="field-label">Start preparation<input id="plan-start" type="datetime-local" value="'+localDate(n.planStart||Date.parse(n.created))+'"></label><label class="field-label">Minutes to enjoy dinner<input id="dinner-minutes" type="number" min="10" max="120" value="'+(n.dinnerMinutes||25)+'"></label>'+button('Save timeline','save-timeline','','primary')+'</details>':'')+'</section>';}
function localDate(t){const d=new Date(t);return new Date(t-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function choose(){const food=draft.mode==='meal';const catalog=(food?filterMeals(search,mealCategory,mealTime,mealCuisine).filter(m=>dietFits(m,draft.prefs.diet)):shows.filter(s=>draft.prefs.catalog==='Original demo titles'?!s.source&&!s.custom:!!s.source||s.custom)).filter(x=>food||(x.name+' '+(x.genre||x.subtitle)).toLowerCase().includes(search.toLowerCase()));return `${steps(0)}${title(food?'Supper → screen':'Screen → supper',food?'What’s for dinner?':'What are you in the mood to watch?',food?'Pick your planned meal. We’ll help find its evening companion.':'Choose a story. We’ll find a dinner that fits its atmosphere.')}<div class="catalog-toolbar"><div class="switcher">${button('Start with supper','start','data-mode="meal"',food?'selected':'')}${button('Start with a watch','start','data-mode="watch"',!food?'selected':'')}</div><label class="search"><span>⌕</span><input id="catalog-search" type="search" placeholder="${food?'Search meals or ingredients…':'Search titles or genres…'}" value="${esc(search)}" aria-label="Search catalog"></label></div>${!food?'<p class="catalog-note">Browse the selected catalog below. Featured movies and series use their promotional artwork. Other titles use illustrative scenery. Food photographs represent recipe styles.</p>':''}${!food?`<section class="catalog-expand panel"><div><p class="eyebrow">Your evening has no shortlist</p><h2>Already have something in mind?</h2><p>Find a movie or series, or add any title yourself. Choose the exact episode before pairing.</p></div><div class="actions">${button('Search the wider catalog ↗','wide-search','','primary')}${button('Add my own title','manual-title')}</div></section>`:''}${food?`<div class="recipe-filters"><label>Food preference<select id="meal-diet">${foodPreferences.map(d=>`<option ${d===draft.prefs.diet?'selected':''}>${d}</option>`).join('')}</select></label><label>Category<select id="meal-category">${mealCategories.map(c=>`<option ${c===mealCategory?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Cuisine inspiration<select id="meal-cuisine">${mealCuisines.map(c=>`<option ${c===mealCuisine?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Ready in<select id="meal-time">${[[60,'Any cooking time'],[15,'15 minutes'],[30,'30 minutes'],[45,'45 minutes']].map(([v,l])=>`<option value="${v}" ${mealTime===v?'selected':''}>${l}</option>`).join('')}</select></label><p id="recipe-count" aria-live="polite">${catalog.length} of ${meals.length} recipes</p></div><p class="catalog-note">Meals for different appetites, including meat, poultry, seafood and vegetarian options. Some use ready-cooked ingredients; check the list. Photos represent the category.</p>`:''}<div id="catalog-grid" class="cards">${(food?catalog.slice(0,recipeLimit):catalog).map(x=>food?mealCard(x):showCard(x)).join('')||'<div class="empty"><h2>No matches yet.</h2><p>Try a shorter search or browse the full catalog.</p></div>'}</div>${food?`<div class="recipe-more">${button('Show more recipes','more-recipes',catalog.length>recipeLimit?'':'hidden','full')}</div>`:''}`;}
function runtimeNotice(){const show=draft.mode==='watch'?showById(draft.sourceId):null;if(!show||show.minutes<=draft.prefs.watchTime)return '';return '<div class="memory-note"><div><strong>'+esc(show.name)+' needs '+show.minutes+' minutes.</strong><p>Your viewing limit is '+draft.prefs.watchTime+' minutes, so this title cannot produce a pairing yet.</p>'+button('Allow enough time for this title','fit-runtime','','primary')+'</div></div>';}
function preferencesPage(){const food=draft.mode==='meal',source=food?mealById(draft.sourceId):showById(draft.sourceId);if(!source)return choose();return `${steps(1)}${title('Made for your evening','Make it your kind of night.','A few shared preferences. Better choices for everyone.','choose')}<div class="split"><aside class="selection-summary ${!food?artClass(source):''}"><img src="${food?mealPhoto(source):watchImg(source)}" alt="${esc(source.name)}"><div><p class="eyebrow">${food?'Tonight’s dinner':'Tonight’s watch'}</p><h2>${esc(source.name)}</h2><p>${source.minutes} min · ${food?source.effort:source.genre}</p>${button('Change '+(food?'meal':'watch'),'go','data-to="choose"','text-btn')}</div></aside><section class="preferences panel"><div class="preference"><label for="people">Who’s joining?</label><div class="people-control">${button('−','people','data-delta="-1" aria-label="One fewer person"')}<span><strong>${draft.prefs.people}</strong> ${draft.prefs.people===1?'person':'people'}</span>${button('+','people','data-delta="1" aria-label="One more person"')}</div></div><div class="preference"><h3>How should we pair?</h3>${chips('pairingStyle',[['Atmosphere','Match the mood'],['Cuisine inspiration','Cuisine inspiration'],['Practical','Use my kitchen']],draft.prefs.pairingStyle||'Atmosphere')}<p class="muted">Choose the atmosphere, a cuisine direction, or ingredients and cooking time.</p></div><div class="preference"><h3>Tonight feels…</h3>${chips('mood',moods.map(x=>[x,x]),draft.prefs.mood)}</div>${runtimeNotice()}<div class="preference"><h3>Time to watch</h3>${chips('watchTime',[[30,'30 min'],[45,'45 min'],[90,'90 min'],[120,'2 hours'],[180,'3 hours'],[240,'4 hours'],[360,'6 hours'],[600,'10 hours']],draft.prefs.watchTime)}</div><div class="preference"><h3>Time to cook</h3>${chips('cookTime',[[15,'15 min'],[30,'30 min'],[45,'45 min'],[60,'1 hour']],draft.prefs.cookTime)}</div><div class="preference"><h3>Cooking level</h3>${chips('cookLevel',[['Beginner','Beginner'],['Regular','Regular'],['Confident','Confident']],draft.prefs.cookLevel||'Regular')}</div><div class="preference"><h3>Cooking effort</h3>${chips('effort',[['Any','A little time is fine'],['Easy','Keep it easy']],draft.prefs.effort)}</div><div class="preference"><h3>Food preference</h3>${chips('diet',foodPreferences.map(d=>[d,d]),draft.prefs.diet)}</div><div class="preference"><h3>Something to watch</h3>${chips('format',[['Any','Either'],['Movie','Movie'],['TV episode','TV episode']],draft.prefs.format)}</div><label class="check-row"><input type="checkbox" data-change="family" ${draft.prefs.family?'checked':''}> Family-friendly catalog only</label>${votingPanel()}${button('Find our pairings →','recommend','','primary full')}</section></div>`;}
function votingPanel(){return '<section class="voting-box"><p class="eyebrow">Make it a shared choice</p><h3>Two people. One good evening.</h3><p>Pass this screen between you. Each person chooses a mood and can veto one pairing on the next screen.</p><label class="check-row"><input id="voting-enabled" type="checkbox" '+(draft.votes?.length?'checked':'')+'> Plan together</label>'+(draft.votes?.length?draft.votes.map((v,i)=>'<label class="field-label">Person '+(i+1)+' · mood<select data-vote="'+i+'">'+moods.map(m=>'<option '+(m===v.mood?'selected':'')+'>'+m+'</option>').join('')+'</select></label>').join(''):'')+'</section>';}
function connectionPanel(meal,show){const c=pairingConnection(meal,show);return '<div class="connection-note"><span class="badge">'+c.label+'</span><p>'+esc(c.text)+'</p>'+(c.reference?'<p><strong>'+esc(c.reference)+'</strong></p>':'')+(c.source?'<a href="'+esc(c.source)+'" target="_blank" rel="noreferrer">Connection source ↗</a>':'')+'</div>';}
function vetoPanel(p){if(!draft.votes?.length)return '';return '<div class="veto-panel">'+draft.votes.map((v,i)=>button('Person '+(i+1)+': veto this option','veto','data-person="'+i+'" data-pair="'+p.meal.id+':'+p.show.id+'"','text-btn')).join('')+'<small>'+voteFit(p.meal,p.show,draft.votes).map((f,i)=>'Person '+(i+1)+': '+f.mood+' '+(f.matched?'✓':'compromise')).join(' · ')+'</small></div>';}
function results(){const picks=recommend({...draft,memory:household.memory,pantry:household.pantry});return `${steps(2)}<div class="ai-inline-invite"><span>Want a more personal connection?</span>${button('Ask the AI concierge ✦','ai-open','data-pin="true"','primary')}</div>${runtimeNotice()}${household.memory.dislikedIngredients?.length?'<p class="memory-note">Your kitchen preferences exclude: '+esc(household.memory.dislikedIngredients.join(', '))+'.</p>':''}${title('A smaller, better choice',picks.length===3?'Three ways to make a night of it.':picks.length?'A pairing that fits your evening.':'Let’s find a little more room.','Each pairing considers your mood, time, saved food preferences, and the dinner you can make.','preferences')}<div class="summary-chips">${badge(draft.prefs.people+' people')}${badge(draft.prefs.mood)}${badge('Up to '+draft.prefs.watchTime+' min to watch')}${badge(draft.prefs.cookTime+' min to cook')}${badge(draft.prefs.diet)}${badge(draft.prefs.pairingStyle||'Atmosphere')}</div>${draft.votes?.length?'<div class="memory-note">Each person has one veto. A new veto replaces their previous choice. '+draft.votes.map((v,i)=>v.veto?button('Undo person '+(i+1)+' veto','undo-veto','data-person="'+i+'"','text-btn'):'').join('')+'</div>':''}${picks.length?`<div class="pairing-grid">${picks.map((p,i)=>`<article class="pairing-card"><div class="pair-art ${artClass(p.show)}"><img src="${watchImg(p.show)}" alt="${esc(artAlt(p.show))}"><span class="image-badge">${i===0?'Our pick for tonight':'Another lovely option'}</span><div class="pair-title"><p>${esc(p.show.genre)} · ${p.show.minutes} min</p><h2>${esc(p.show.name)}</h2></div></div><div class="pair-meal"><img src="${mealPhoto(p.meal)}" alt="${esc(p.meal.name)}"><div><span class="eyebrow">On the table</span><h3>${p.meal.name}</h3><span>${p.meal.minutes} min · ${p.meal.effort}</span></div></div><div class="pairing-body">${connectionPanel(p.meal,p.show)}${vetoPanel(p)}<p class="eyebrow">Why it fits tonight</p><ul class="reasons">${p.reasons.map(r=>`<li><span>✦</span>${esc(r)}</li>`).join('')}</ul>${button('Plan this night →','pair',`data-meal="${p.meal.id}" data-show="${p.show.id}"`,i===0?'primary full':'full')}</div></article>`).join('')}</div>`:`<div class="empty panel"><h2>Let’s give this evening a little more room.</h2><p>No pairing meets every limit and saved ingredient preference. Edit ingredients to avoid in My kitchen if needed. Imported titles have unverified family suitability and are excluded by the family-only filter. Try more cooking or viewing time, or change your starting choice.</p>${button('Adjust preferences','go','data-to="preferences"','primary')}${button('Choose something else','go','data-to="choose"')}</div>`}<p class="catalog-note">Pairings use a curated, explainable ranking system. ${draft.prefs.catalog==='Real titles'?'Real titles use published runtimes; versions and viewing availability vary by provider.':'This catalog uses original fictional demo titles.'} Featured titles use promotional artwork; other imagery illustrates atmosphere. Streaming playback is not included.</p>`;}
function review(){if(!draft.pair)return results();const meal=mealById(draft.pair.mealId),show=showById(draft.pair.showId),list=ingredients(meal,draft.prefs.people,draft.adapted),all=list.every(x=>draft.confirmed.includes(x.name)),mustAdapt=draft.prefs.diet==='Plant-based'&&!draft.adapted;return `${steps(3)}${themeBadge(draft)}${title('From inspiration to your kitchen','Make this night yours.','Confirm your ingredients, then review one practical adaptation.','results')}<div class="split"><aside class="selection-summary"><img src="${mealPhoto(meal)}" alt="${esc(meal.name)}"><div><p class="eyebrow">Tonight’s pairing</p><h2>${meal.name}</h2><p>With ${esc(show.name)}</p><div class="summary-chips">${badge(meal.minutes+' min cook')}${badge(show.minutes+' min watch')}${badge('Serves '+draft.prefs.people)}</div></div></aside><div class="panel"><h2>From your kitchen</h2><p class="muted">Check what you have. Quantities are scaled for ${draft.prefs.people} ${draft.prefs.people===1?'person':'people'}.</p><div class="ingredients">${list.map(x=>`<label class="ingredient"><input type="checkbox" data-change="ingredient" value="${esc(x.name)}" ${draft.confirmed.includes(x.name)?'checked':''}><span>${esc(x.name)}</span><strong>${x.amount} ${x.unit}</strong></label>`).join('')}</div>${button('Confirm all ingredients','confirm-all','','text-btn')}<div class="adaptation ${draft.adapted?'approved':''}"><p class="eyebrow">${draft.adapted?'✓ Approved adaptation':'One suggested adaptation'}</p><h3>${meal.swap.from} <span>→</span> ${meal.swap.to}</h3><p>${meal.swap.reason}</p>${button(draft.adapted?'Undo adaptation':'Approve this adaptation','adapt','',draft.adapted?'':'primary')}</div><p class="catalog-note">Check package ingredients for your dietary needs. These recipes do not screen for allergies.</p>${mustAdapt?'<p class="inline-note">Approve the adaptation to match your plant-based preference.</p>':''}${!all?`<p class="inline-note">${list.filter(x=>!draft.confirmed.includes(x.name)).length} ingredient(s) still need confirmation.</p>`:''}${button('Confirm our night →','confirm-night',(!all||mustAdapt)?'disabled':'','primary full')}</div></div>`;}
function getNight(){return night&&mealById(night.mealId)&&showById(night.showId)?night:null;}
function tonight(){const n=getNight();if(!n)return '<p>Opening your evening…</p>';const meal=mealById(n.mealId),show=showById(n.showId),step=recipeSteps(meal,n.adapted,n.prefs.cookLevel||'Regular')[n.step];return `${title('Tonight, made simple','Your evening, thoughtfully paired.','One shared plan. A little less deciding.','saved')}${themeBadge(n)}${n.ai?'<section class="ai-saved-note"><p class="eyebrow">✦ Your concierge’s pairing</p><p>'+esc(n.ai.reason)+'</p><p>'+esc(n.ai.ritual)+'</p></section>':''}${!sharedKey?button('Ask your evening concierge ✦','ai-open','','text-btn'):''}${n.rescue?'<p class="memory-note">Evening rescued: '+n.rescue.minutesSaved+' minutes saved. Updated portions and cooking steps are shared with your phone.</p>':''}${connectionPanel(meal,show)}${n.status==='planned'&&!n.watchStarted?button('Rescue tonight ✦','rescue-open','','primary'):''}${timelinePanel(n)}<div class="night-layout"><div><div class="night-art ${artClass(show)}"><img src="${watchImg(show)}" alt="${esc(artAlt(show))}"><div><p class="eyebrow">On your screen</p><h2>${esc(show.name)}</h2><p>${esc(show.genre)} · ${show.minutes} min</p></div></div><div class="night-art food"><img src="${mealPhoto(meal)}" alt="${meal.name}"><div><p class="eyebrow">On your table</p><h2>${meal.name}</h2><p>${meal.minutes} min · ${n.prefs.people} people ${n.adapted?'· Adaptation approved':''}</p></div></div></div><aside class="panel night-panel"><p class="eyebrow">The evening plan</p><h2>Good food.<br>Something to look forward to.</h2><div class="timeline"><div><b>1</b><span><strong>Cook together</strong><small>About ${meal.minutes} minutes</small></span></div><div><b>2</b><span><strong>Settle in for dinner</strong><small>A moment to enjoy what you made</small></span></div><div><b>3</b><span><strong>${esc(show.name)}</strong><small>${show.minutes} minutes of ${show.mood.toLowerCase()}</small></span></div></div><div class="live-status"><span class="status-dot"></span><div><strong>${n.status==='ready'?'Dinner is ready':n.status==='complete'?'Evening remembered':n.status==='cooking'?'Cooking in progress':'Ready when you are'}</strong><p>${n.status==='cooking'?`Step ${n.step+1}: ${step.title}`:'Your plan is saved to this household.'}</p></div></div>${button(n.status==='cooking'?'Continue cooking →':'Start cooking →','go',`data-to="cook/${n.id}"`,'primary full')}${button('Send cooking steps to phone','share','','full')}${button('Reflect on this evening','go',`data-to="feedback/${n.id}"`,'text-btn full')}<div class="watch-session"><h3>Your viewing time</h3><p>${n.watchStarted?'Viewing timer is running.':'Use a timer to keep your evening on track.'}</p>${n.watchStarted?'<strong id="watch-clock"></strong>':button('Begin viewing timer','watch-start','','text-btn')}<small>This starts a timer, not a film or stream.</small>${show.source?`<a class="btn full" href="${show.source}" target="_blank" rel="noreferrer">View title & viewing options ↗</a><small>Opens the provider’s page. Availability and subscriptions vary by region. Rating: ${show.rating}.</small>`:(show.custom?'<small>Your title and runtime. Check viewing availability in your streaming app.</small>':'<small>Fictional title from an earlier saved plan.</small>')}</div></aside></div>`;}
function cookPage(){const n=getNight();if(!n)return '<p>Opening your cooking steps…</p>';const meal=mealById(n.mealId),stepsList=recipeSteps(meal,n.adapted,n.prefs.cookLevel||'Regular'),step=stepsList[n.step];return `<div class="cook-top"><div><p class="eyebrow">${sharedKey?'Phone companion · connected to your TV plan':'Your cooking companion'}</p><h2>${meal.name}</h2></div><span class="badge">Serves ${n.prefs.people}</span></div>${timelinePanel(n)}<div class="cooking-layout"><div class="cooking-photo"><img src="${mealPhoto(meal)}" alt="${meal.name}"><div>${n.adapted?badge(meal.swap.to+' approved'):badge('Original recipe')}<p>Paired with ${showById(n.showId).name}</p></div></div><section class="panel cooking-panel"><div class="step-count"><span>Step ${n.step+1} of ${stepsList.length}</span><span>${Math.round((n.step+1)/stepsList.length*100)}%</span></div><progress max="${stepsList.length}" value="${n.step+1}" aria-label="Recipe progress"></progress><h1>${step.title}</h1><p class="eyebrow">${esc(n.prefs.cookLevel||"Regular")} guidance</p><p class="instruction" style="white-space:pre-line">${esc(step.instruction)}</p>${step.seconds?`<div class="timer-box"><div><p class="eyebrow">Kitchen timer</p><strong id="timer-clock">${formatTime(n.timer?Math.max(0,(n.timer-Date.now())/1000):step.seconds)}</strong></div>${button(n.timer?'Stop timer':'Start '+Math.round(step.seconds/60)+'-minute timer','timer','','primary')}</div>`:''}${n.status==='ready'?'<div class="success-note">✓ Dinner is ready. Your TV plan has been updated.</div>':''}<div class="cook-buttons">${button('← Previous','step',`data-step="${n.step-1}" ${n.step===0?'disabled':''}`)}${n.step===stepsList.length-1?button('Dinner is ready ✓','finish-cooking','','primary'):button('Next step →','step',`data-step="${n.step+1}"`,'primary')}</div>${button('Ask the AI cooking coach ✦','ai-cook-help','','full')}<details><summary>Ingredients & approved changes</summary><ul class="ingredient-list">${ingredients(meal,n.prefs.people,n.adapted).map(x=>`<li>${x.amount} ${x.unit} ${x.name}</li>`).join('')}</ul></details>${!sharedKey?button('Back to the TV plan','go',`data-to="tonight/${n.id}"`,'text-btn'): '<p class="catalog-note">Your progress syncs with the TV every few seconds. Keep this link for this evening.</p>'}</section></div>`;}
function feedbackPage(){const n=getNight();if(!n)return '';return `${title('After the evening','What should we remember?','A little feedback makes the next night more personal.','tonight/'+n.id)}<div class="feedback-layout"><div class="feedback-image"><img src="${img(mealById(n.mealId).image)}" alt="${mealById(n.mealId).name}"><div><h2>${mealById(n.mealId).name}</h2><p>With ${showById(n.showId).name}</p></div></div><section class="panel"><h3>How was dinner?</h3>${feedbackChips('meal',[['again','Make it again'],['okay','It was okay'],['skip','Try another meal']])}<h3>How did the pairing feel?</h3>${feedbackChips('pairing',[['great','Great together'],['okay','Pretty good'],['miss','Not quite right']])}<div class="memory-review"><p class="eyebrow">You’re in control of the memory</p><label class="check-row"><input type="checkbox" data-change="shorter" ${feedback.shorter?'checked':''}> Favor episodes under 45 minutes next time</label><label class="check-row"><input type="checkbox" data-change="rememberMood" ${feedback.rememberMood?'checked':''}> Remember that we like ${n.prefs.mood.toLowerCase()} evenings</label><label class="check-row"><input type="checkbox" data-change="rememberCuisine" ${feedback.rememberCuisine?'checked':''}> Remember this meal’s ${mealById(n.mealId).cuisine} cuisine inspiration</label><label class="check-row"><input type="checkbox" data-change="preferEasy" ${feedback.preferEasy?'checked':''}> Favor easier cooking next time</label><p>${feedback.meal==='again'?'This meal will be saved as a household favorite.':'Your meal rating will be saved with this night.'} You can edit your preferences in My kitchen.</p></div>${button('Save feedback & see the next picks →','save-feedback','','primary full')}</section></div>`;}
function feedbackChips(field,options){return `<div class="chips">${options.map(([v,label])=>`<button class="chip ${feedback[field]===v?'selected':''}" data-action="feedback-choice" data-field="${field}" data-value="${v}" aria-pressed="${feedback[field]===v}">${label}</button>`).join('')}</div>`;}
function saved(){const list=household.nights.filter(n=>savedFilter==='all'||(savedFilter==='complete'?n.status==='complete':n.status!=='complete'));return `${title('Your collection','Good nights deserve a second helping.','Your dinners and stories, remembered together.')}<div class="chips collection-filter">${[['all','All nights'],['planned','In progress'],['complete','Enjoyed together']].map(([v,l])=>`<button class="chip ${v===savedFilter?'selected':''}" data-action="filter" data-filter="${v}">${l}</button>`).join('')}</div>${list.length?`<div class="cards saved-grid">${list.map(n=>{const m=mealById(n.mealId),s=showById(n.showId);return `<article class="saved-card"><img src="${mealPhoto(m)}" alt="${m.name}"><div class="card-body"><span class="eyebrow">${n.status==='complete'?'Enjoyed together':n.status==='ready'?'Dinner is ready':'Your evening plan'}</span><h3>${m.name}</h3><p>${esc(s.name)}</p><div class="meta"><span>${m.minutes} min cook</span><span>${esc(s.minutes)} min watch</span></div>${n.feedback?badge(n.feedback.meal==='again'?'Make it again':'Feedback saved'):''}<div class="actions">${button(n.status==='complete'?'Plan again':'Continue →',n.status==='complete'?'again':'go',n.status==='complete'?`data-id="${n.id}"`:`data-to="tonight/${n.id}"`,'primary')}${button('Remove','remove',`data-id="${n.id}"`,'text-btn')}</div></div></article>`;}).join('')}</div>`:`<div class="empty panel"><h2>${savedFilter==='all'?'Your first great night starts here.':'No nights in this collection yet.'}</h2><p>Choose dinner or a watch, and save your first pairing.</p>${button('Plan a night →','start','data-mode="meal"','primary')}</div>`}`;}
function kitchen(){const pantryItems=[...new Set(meals.flatMap(m=>m.ingredients.map(x=>x[0])).concat(meals.map(m=>m.swap.to)))].sort((a,b)=>a.localeCompare(b));return `${title('The things that make it yours','Your kitchen. Your preferences.','Saved for your next evening, and always yours to change.')}<div class="split"><section class="panel"><p class="eyebrow">A useful starting point</p><h2>What’s in your kitchen?</h2><p class="muted">Saved ingredients help prefill your checklist. You’ll still review them before cooking.</p><div class="pantry-grid">${pantryItems.map(x=>`<label class="check-row"><input type="checkbox" data-change="pantry" value="${esc(x)}" ${household.pantry.includes(x)?'checked':''}>${x}</label>`).join('')}</div>${button('Save my kitchen','save-pantry','','primary full')}</section><section class="panel"><p class="eyebrow">Learning from your evenings</p><h2>A little more you, every time.</h2><label class="check-row"><input id="memory-shorter" type="checkbox" ${household.memory.shorter?'checked':''}> Favor TV episodes under 45 minutes</label><label class="field-label" for="memory-mood">Favorite evening mood</label><select id="memory-mood"><option value="">No saved preference</option>${moods.map(m=>`<option ${household.memory.preferredMood===m?'selected':''}>${m}</option>`).join('')}</select><label class="field-label" for="disliked-ingredients">Ingredients to avoid</label><input id="disliked-ingredients" placeholder="e.g. mushrooms, olives" value="${esc((household.memory.dislikedIngredients||[]).join(', '))}"><p class="catalog-note">Comma-separated food preferences. Matches ingredient names; this is not an allergy safety check.</p><label class="field-label">Favorite cuisine inspirations</label>${['European','Mediterranean','Asian','Americas'].map(c=>'<label class="check-row"><input type="checkbox" data-cuisine="'+c+'" '+(household.memory.favoriteCuisines?.includes(c)?'checked':'')+'>'+c+'</label>').join('')}<label class="check-row"><input type="checkbox" id="memory-easy" ${household.memory.preferredEffort==='Easy'?'checked':''}> Favor easier recipes</label><div class="memory-list"><h3>Meals you’d make again</h3><p>${household.memory.favoriteMeals?.length?household.memory.favoriteMeals.map(id=>esc(mealById(id)?.name)).join('<br>'):'Favorites appear here after you share feedback.'}</p></div>${button('Save preferences','save-memory','','primary full')}<div class="household-note"><h3>Your household</h3><p>Your nights are stored online. This browser holds the access key; phone cooking links share one night, not your whole collection.</p></div></section></div>`;}
function render(){registerShows([...(household?.titles||[]),...(household?.nights||[]).map(n=>n.show),night?.show,draft.externalShow]);const focused=document.activeElement;const focusText=focused?.textContent;const focusData=focused?.dataset?.action?{...focused.dataset}:null;if(!household&&!sharedKey)return;const r=route(),pages={concierge:aiUI.page,home,choose,preferences:preferencesPage,results,review,tonight,cook:cookPage,feedback:feedbackPage,saved,kitchen,'movie-nights':movieNightsPage,phone:cookPage};app.innerHTML=(sharedKey?`<header class="topbar"><a class="brand" href="/app/"><img src="/app/images/crave-frame-3d-v5.png" alt="">Crave Frame</a>${badge('Cooking companion')}</header>`:header())+`<main id="main-content" class="page-${r}">${(pages[r]||home)()}</main>`+footer();if(focusData){const targets=[...app.querySelectorAll('[data-action]')];(targets.find(el=>Object.entries(focusData).every(([k,v])=>el.dataset[k]===v))||targets.find(el=>el.dataset.action===focusData.action&&el.textContent===focusText))?.focus({preventScroll:true});}updateClocks();}
function formatTime(seconds){const s=Math.max(0,Math.ceil(seconds));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function updateClocks(){if(night){const timer=$('#timer-clock');if(timer&&night.timer)timer.textContent=night.timer<=Date.now()?'Time’s up ✓':formatTime((night.timer-Date.now())/1000);const watch=$('#watch-clock');if(watch&&night.watchStarted)watch.textContent=formatTime(Math.max(0,showById(night.showId).minutes*60-(Date.now()-night.watchStarted)/1000))+' remaining';}}
function rescueReview(){const o=rescueDraft.choice,m=mealById(o.mealId),list=ingredients(m,rescueDraft.request.people,rescueDraft.adapted);modal('<p class="eyebrow">Approve your changed evening</p><h2>'+esc(m.name)+'</h2><p>With '+esc(o.showName)+' · '+o.people+' people</p><p>'+esc(o.tradeoff)+' '+o.minutesSaved+' minutes saved.</p><div class="ingredients">'+list.map(i=>'<label class="ingredient"><input type="checkbox" data-rescue-ingredient value="'+esc(i.name)+'"><span>'+esc(i.name)+'</span><strong>'+i.amount+' '+i.unit+'</strong></label>').join('')+'</div><div class="adaptation"><h3>'+esc(m.swap.from)+' → '+esc(m.swap.to)+'</h3><p>'+esc(m.swap.reason)+'</p>'+button(rescueDraft.adapted?'Undo adaptation':'Approve adaptation','rescue-adapt','','text-btn')+'</div><p>Review every ingredient. Approval replaces this saved pairing and its shared cooking steps; cooking will begin at step one.</p>'+button('Approve changed evening','rescue-approve','','primary full'));}
function modal(content){$('#dialog')?.remove();const d=document.createElement('dialog');d.id='dialog';d.innerHTML=`<button class="dialog-close" data-action="close" aria-label="Close dialog">×</button>${content}`;document.body.append(d);d.showModal();d.addEventListener('click',e=>{if(e.target===d)d.close();});d.addEventListener('close',()=>d.remove());}
async function share(){const {key:shareKey}=await api(`nights/${night.id}/share`,'POST');shareLink=location.origin+'/app/?cook='+shareKey;const qr=await QRCode.toDataURL(shareLink,{margin:2,width:260,color:{dark:'#182015',light:'#f5eedc'}});modal(`<p class="eyebrow">One evening. Two screens.</p><h2>Take the cooking with you.</h2><p>Scan with your phone camera. The evening plan stays on TV, and cooking progress syncs between screens.</p><img class="qr" src="${qr}" alt="QR code to open this night’s cooking steps"><label class="field-label" for="share-url">Cooking link</label><input id="share-url" value="${esc(shareLink)}" readonly><div class="actions">${button('Copy link','copy-share','','primary')}<a class="btn" href="${esc(shareLink)}" target="_blank" rel="noreferrer">Open companion ↗</a></div><p class="catalog-note">Anyone with this link can view this recipe and update its cooking progress. It expires in 30 days.</p>`);}
async function cookUpdate(data){night=await api(sharedKey?'shared/'+sharedKey:'nights/'+night.id,'PATCH',{...data,mealId:night.mealId});render();}
let selectedProvider=null;
function titleForm(detail={}){modal(`<p class="eyebrow">Screen → supper</p><h2>Make it your evening.</h2><p>Choose a mood and cuisine direction. These guide the pairing; they are not verified facts about the story.</p><label class="field-label" for="custom-name">Movie or episode title</label><input id="custom-name" maxlength="160" value="${esc(detail.name||'')}" ${selectedProvider?'readonly':''}><div class="form-grid"><label>Format<select id="custom-kind"><option>Movie</option><option ${selectedProvider?.type==='tv'?'selected':''}>TV episode</option></select></label><label>Viewing minutes<input id="custom-minutes" type="number" min="1" max="600" value="${detail.minutes||''}" placeholder="Enter runtime"></label><label>Mood<select id="custom-mood">${moods.map(m=>' <option>'+m+'</option>').join('')}</select></label><label>Cuisine inspiration<select id="custom-cuisine">${['Any','European','Mediterranean','Asian','Americas'].map(m=>'<option>'+m+'</option>').join('')}</select></label></div><p class="catalog-note">${detail.minutes?'Published runtime loaded.':'Runtime is missing or user supplied: enter the duration of your planned viewing.'} Family suitability is not verified for imported titles.</p>${button('Find a dinner for this →','save-title','','primary full')}`);}
function themeBadge(data){const t=movieNightById(data?.themeId);return t&&t.mealId===(data.mealId||data.pair?.mealId)?`<div class="theme-note"><p class="eyebrow">Inspired movie night</p><h3>${esc(t.heading)}</h3><p>Inspired by ${esc(t.movie)}. Independent pairing, not an official recipe.</p></div>`:'';}
function movieNightsPage(){const filtered=movieNights.filter(t=>(t.movie+' '+t.heading+' '+t.mealName).toLowerCase().includes(themeSearch.toLowerCase()));return `${title('A little cinema at the table','Make it a movie night.','100 inspired pairings. Real dish names. A playful title when you want one.')}<div class="catalog-toolbar"><p class="muted">These themes do not add to the ${meals.length}-recipe count.</p><label class="search"><input id="theme-search" type="search" placeholder="Search a film or dinner…" value="${esc(themeSearch)}" aria-label="Search inspired nights"></label></div><p class="catalog-note">Independent movie-inspired pairings, not recipes from the films or official collaborations. Photographs represent dish categories.</p><div id="theme-grid" class="cards">${filtered.slice(0,themeLimit).map(themeCard).join('')||'<p>No matches. Try a different movie or dish.</p>'}</div><p id="theme-count" class="catalog-note">${filtered.length} inspired pairings</p>${button('Show more movie nights','more-themes',filtered.length>themeLimit?'':'hidden','full')}`;}
function themeCard(t){return `<article class="saved-card theme-card"><img src="${img(t.image)}" alt="Representative ${esc(t.category.toLowerCase())} photograph" loading="lazy"><div class="card-body"><p class="eyebrow">${esc(t.movie)} · ${t.year}</p><h3>${esc(t.heading)}</h3><p class="real-dish">${esc(t.mealName)}</p><div class="meta"><span>${t.minutes} min</span><span>${esc(t.category)}</span></div>${button('Plan this inspired night →','theme-night',`data-id="${t.id}"`,'primary full')}</div></article>`;}
const actions={
 ...aiUI.actions,
 'ai-cook-help':()=>modal('<p class="eyebrow">Alongside your recipe</p><h2>Ask your cooking coach.</h2><p>The coach can see this recipe, your portions and the current step.</p><label class="field-label" for="cook-question">What would help?</label><textarea id="cook-question" maxlength="1200" placeholder="How can I tell when this step is ready?"></textarea>'+button('Ask the coach ✦','ai-cook-send','','primary full')+'<div id="cook-answer" aria-live="polite"></div>'),
 'ai-cook-send':async()=>{const target=$('#cook-answer');target.textContent='Thinking through this step…';try{const r=await api(sharedKey?'shared/'+sharedKey+'/ai':'ai','POST',{mode:'coach',prompt:$('#cook-question').value,nightId:night.id});target.innerHTML='<p>'+esc(r.answer)+'</p><ul>'+r.tips.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul><p class="catalog-note">Advice only. Your saved recipe has not changed.</p>';}catch(e){target.textContent=e.message;}},

 'fit-runtime':()=>{draft.prefs=selectedWatchPrefs(draft.prefs,showById(draft.sourceId));persist();render();},
 'rescue-open':()=>{rescueDraft=null;modal('<p class="eyebrow">A change of plans</p><h2>Let’s rescue tonight.</h2><p>Find alternatives before cooking begins. Nothing changes until you review the new ingredients and approve.</p><label class="field-label">Starting late by<input id="rescue-delay" type="number" min="0" max="120" value="15"> minutes</label><label class="field-label">People at the table<input id="rescue-people" type="number" min="1" max="8" value="'+night.prefs.people+'"></label><label class="field-label">Missing ingredients<input id="rescue-missing" placeholder="e.g. mushrooms, basil"></label><label class="check-row"><input id="rescue-watch" type="checkbox" checked> Allow a different movie or shorter episode</label>'+button('Find rescue options →','rescue-find','','primary full'));},
 'rescue-find':async()=>{const request={delay:Number($('#rescue-delay').value),people:Number($('#rescue-people').value),missing:$('#rescue-missing').value.split(',').map(s=>s.trim()).filter(Boolean),allowWatchChange:$('#rescue-watch').checked};const result=await api('nights/'+night.id+'/rescue','POST',{request});rescueDraft={...result,request};modal('<p class="eyebrow">Review the tradeoffs</p><h2>A little adjustment. A good night.</h2>'+result.options.map((o,i)=>'<article class="rescue-option"><h3>'+esc(o.mealName)+'</h3><p>With '+esc(o.showName)+'</p><p>'+esc(o.tradeoff)+'</p><div class="meta"><span>'+o.minutesSaved+' min saved</span><span>'+o.people+' people</span><span>'+o.total+' min including dinner</span></div>'+button('Review ingredients →','rescue-review','data-index="'+i+'"','primary')+'</article>').join('')+(result.options.length?'':'<p>No option fits all the changes. Try less delay, fewer exclusions, or allow a different watch.</p>')+button('Change the request','rescue-open','','text-btn'));},
 'rescue-review':el=>{rescueDraft.choice=rescueDraft.options[Number(el.dataset.index)];rescueDraft.adapted=false;rescueReview();},
 'rescue-adapt':()=>{rescueDraft.adapted=!rescueDraft.adapted;rescueReview();},
 'rescue-approve':async()=>{const o=rescueDraft.choice;night=await api('nights/'+night.id+'/rescue','POST',{request:rescueDraft.request,revision:rescueDraft.revision,apply:true,mealId:o.mealId,showId:o.showId,adapted:rescueDraft.adapted,confirmed:[...document.querySelectorAll('[data-rescue-ingredient]:checked')].map(el=>el.value)});household=await api('household');$('#dialog').close();rescueDraft=null;render();toast('Rescued evening approved. Your phone link now has the updated recipe.');},
 veto:el=>{draft.votes[Number(el.dataset.person)].veto=el.dataset.pair;persist();render();},
 'undo-veto':el=>{draft.votes[Number(el.dataset.person)].veto=null;persist();render();},
 'save-timeline':async()=>{const planStart=new Date($('#plan-start').value).getTime();if(!Number.isFinite(planStart))throw Error('Choose a start date and time.');night=await api('nights/'+night.id,'PATCH',{planStart,dinnerMinutes:Number($('#dinner-minutes').value)});render();toast('Timeline saved and shared with your phone.');},
 featured:el=>{const d=featuredEvenings.find(x=>x.id===el.dataset.id),show=showById(d.showId);draft={mode:d.mode,sourceId:d.mode==='meal'?d.mealId:d.showId,demoId:d.id,prefs:{...defaults,mood:show.mood,cookTime:45,watchTime:show.minutes>120?180:120},pair:null,adapted:false,confirmed:[]};persist();go('preferences');},
 'more-recipes':()=>{recipeLimit+=24;render();},
 'more-themes':()=>{themeLimit+=20;render();},
 'theme-night':async el=>{const t=movieNightById(el.dataset.id);if(!t)return;const found=await api('catalog/search?q='+encodeURIComponent(t.movie));const normalize=s=>s.toLowerCase().replace(/[^a-z0-9]/g,'');const movie=found.results.find(m=>m.type==='movie'&&m.year===t.year&&normalize(m.name)===normalize(t.movie));if(!movie)throw Error('This movie edition is unavailable right now. Try searching from Start with a watch.');const d=await api('catalog/details?type=movie&id='+movie.id);if(!d.minutes)throw Error('This title has no runtime listed. Add it manually from Start with a watch.');const meal=mealById(t.mealId);const show=await api('catalog/select','POST',{provider:{type:'movie',id:movie.id},mood:t.mood,cuisine:meal.cuisine,minutes:d.minutes});registerShows([show]);draft={mode:'watch',sourceId:show.id,externalShow:show,themeId:t.id,themedMealId:meal.id,pair:null,adapted:false,confirmed:[],prefs:{...draft.prefs,mood:t.mood,family:false,format:'Movie',catalog:'Real titles',watchTime:[30,45,90,120,180,240,360,600].find(n=>n>=show.minutes)||600,cookTime:[15,30,45,60].find(n=>n>=meal.minutes),effort:'Any'}};persist();go('preferences');toast('Inspired night selected. Review your preferences before choosing a pairing.');},

 'manual-title':()=>{selectedProvider=null;titleForm();},
 'wide-search':async()=>{const status=await api('catalog/status');modal(`<p class="eyebrow">Beyond the featured collection</p><h2>Find your story.</h2><p>${status.connected?'Search movies and TV series. Pick the year and edition you mean.':'TMDB is not connected yet. Featured titles and the add-your-own flow are ready to use.'}</p><div class="actions"><input id="wide-query" type="search" maxlength="120" placeholder="Movie or series name" aria-label="Search movies and series">${button('Search','catalog-search',status.connected?'':'disabled','primary')}</div><div id="wide-results" aria-live="polite"></div>${button('Add my own title','manual-title','','text-btn')}`);},
 'catalog-search':async()=>{const target=$('#wide-results');target.innerHTML='<p>Finding titles…</p>';try{const data=await api('catalog/search?q='+encodeURIComponent($('#wide-query').value));target.innerHTML=data.results.map(x=>`<button class="catalog-result" data-action="catalog-detail" data-type="${x.type}" data-id="${x.id}">${tmdbImage(x.posterPath)?`<img class="search-poster" src="${tmdbImage(x.posterPath)}" alt="${esc(x.name)} poster" loading="lazy">`:''}<strong>${esc(x.name)}</strong><span>${esc(x.year||'Year unavailable')} · ${x.type==='tv'?'TV series':'Movie'}</span><small>${esc(x.description)}</small></button>`).join('')||'<p>No matches. Try another spelling, or add your own title.</p>';}catch(e){target.textContent=e.message;}},
 'catalog-detail':async el=>{selectedProvider={type:el.dataset.type,id:Number(el.dataset.id)};const d=await api('catalog/details?type='+selectedProvider.type+'&id='+selectedProvider.id);if(selectedProvider.type==='movie'){titleForm(d);return;}modal(`<p class="eyebrow">Choose the episode</p><h2>${esc(d.name)}</h2><p>Your viewing time will use the selected episode, not a whole season.</p><div class="chips">${d.seasons.map(s=>button(esc(s.name),'catalog-season',`data-number="${s.number}"`)).join('')}</div><div id="episode-results" aria-live="polite"></div>`);},
 'catalog-season':async el=>{selectedProvider.season=Number(el.dataset.number);const d=await api('catalog/details?type=tv&id='+selectedProvider.id+'&season='+selectedProvider.season);$('#episode-results').innerHTML=d.episodes.map(e=>button(esc('E'+e.number+' · '+e.name+' · '+(e.minutes?e.minutes+' min':'Runtime unavailable')),'catalog-episode',`data-number="${e.number}" data-minutes="${e.minutes||''}" data-name="${esc(e.name)}"`,'episode-choice')).join('')||'<p>No episodes listed. Add the episode manually.</p>';},
 'catalog-episode':el=>{selectedProvider.episode=Number(el.dataset.number);titleForm({name:'S'+selectedProvider.season+' E'+selectedProvider.episode+' · '+el.dataset.name,minutes:Number(el.dataset.minutes)});},
 'save-title':async()=>{draft.demoId=null;draft.themeId=null;draft.themedMealId=null;const show=await api('catalog/select','POST',{name:$('#custom-name').value,minutes:Number($('#custom-minutes').value),kind:$('#custom-kind').value,mood:$('#custom-mood').value,cuisine:$('#custom-cuisine').value,provider:selectedProvider});registerShows([show]);draft={...draft,mode:'watch',sourceId:show.id,externalShow:show,pair:null,prefs:{...selectedWatchPrefs(draft.prefs,show),family:false,format:'Any',catalog:'Real titles'}};persist();$('#dialog').close();go('preferences');},

 retry:()=>load(),go:el=>go(el.dataset.to),close:()=>$('#dialog')?.close(),
 start:el=>{draft.ai=null;draft.demoId=null;draft.themeId=null;draft.themedMealId=null;recipeLimit=24;draft.mode=el.dataset.mode;draft.prefs.catalog='Real titles';search='';draft.pair=null;persist();go('choose');},
 'mood-start':el=>{draft.prefs.mood=el.dataset.mood;draft.mode='meal';search='';persist();go('choose');},
 'quick-meal':el=>{draft.demoId=null;draft.themeId=null;draft.themedMealId=null;draft.mode='meal';draft.sourceId=el.dataset.id;persist();go('preferences');},
 choose:el=>{draft.demoId=null;draft.themeId=null;draft.themedMealId=null;draft.sourceId=el.dataset.id;draft.pair=null;if(draft.mode==='watch')draft.prefs=selectedWatchPrefs(draft.prefs,showById(draft.sourceId));persist();go('preferences');},
 people:el=>{draft.prefs.people=Math.max(1,Math.min(8,draft.prefs.people+Number(el.dataset.delta)));persist();render();},
 pref:el=>{draft.ai=null;draft.prefs[el.dataset.field]=['cookTime','watchTime'].includes(el.dataset.field)?Number(el.dataset.value):el.dataset.value;persist();render();},
 recommend:()=>{persist();go('results');},
 pair:el=>{draft.ai=null;draft.pair={mealId:el.dataset.meal,showId:el.dataset.show};draft.adapted=false;draft.confirmed=[...household.pantry];persist();go('review');},
 adapt:()=>{draft.adapted=!draft.adapted;const m=mealById(draft.pair.mealId);draft.confirmed=draft.confirmed.filter(x=>x!==m.swap.from&&x!==m.swap.to);persist();render();},
 'confirm-all':()=>{draft.confirmed=ingredients(mealById(draft.pair.mealId),draft.prefs.people,draft.adapted).map(x=>x.name);persist();render();},
 'confirm-night':async()=>{night=await api('nights','POST',{...draft.pair,prefs:draft.prefs,adapted:draft.adapted,confirmed:draft.confirmed,themeId:draft.themeId,ai:draft.ai});household=await api('household');go('tonight/'+night.id);},
 share, 'copy-share':async()=>{try{await navigator.clipboard.writeText(shareLink);toast('Cooking link copied.');}catch{$('#share-url').select();toast('Select and copy the cooking link.');}},
 step:el=>cookUpdate({step:Number(el.dataset.step)}),timer:()=>{const step=recipeSteps(mealById(night.mealId),night.adapted,night.prefs.cookLevel||'Regular')[night.step];return cookUpdate({timer:night.timer?null:Date.now()+step.seconds*1000});},
 'finish-cooking':async()=>{await cookUpdate({complete:true});toast('Dinner is ready. Your TV plan is up to date.');},
 'watch-start':async()=>{night=await api('nights/'+night.id,'PATCH',{watchStarted:true});render();},
 'feedback-choice':el=>{feedback[el.dataset.field]=el.dataset.value;render();},
 'save-feedback':async()=>{const foodFeedback=!feedback.shorter&&(feedback.rememberCuisine||feedback.preferEasy);household=await api(`nights/${night.id}/feedback`,'POST',feedback);draft={mode:foodFeedback?'watch':'meal',sourceId:foodFeedback?night.showId:night.mealId,prefs:{...night.prefs,format:'Any'},pair:null,adapted:false,confirmed:[]};persist();toast('Feedback saved. Look for “Your saved” explanations in your next picks.');go('results');},
 filter:el=>{savedFilter=el.dataset.filter;render();},
 again:el=>{const n=household.nights.find(x=>x.id===el.dataset.id);draft={mode:'meal',sourceId:n.mealId,prefs:{...n.prefs},pair:{mealId:n.mealId,showId:n.showId},adapted:n.adapted,confirmed:[],themeId:n.themeId};persist();go('review');},
 remove:el=>{modal(`<h2>Remove this saved night?</h2><p>Its cooking link will stop working. Your household preferences will stay saved.</p><div class="actions">${button('Keep it','close')}${button('Remove night','confirm-remove',`data-id="${el.dataset.id}"`,'primary')}</div>`);},
 'confirm-remove':async el=>{household=await api('nights/'+el.dataset.id,'DELETE');$('#dialog').close();render();toast('Night removed.');},
 'save-pantry':async()=>{household=await api('pantry','PUT',{items:[...document.querySelectorAll('[data-change="pantry"]:checked')].map(x=>x.value)});toast('Your kitchen is saved.');},
 'save-memory':async()=>{household=await api('preferences','PUT',{prefs:household.prefs,memory:{shorter:$('#memory-shorter').checked,preferredMood:$('#memory-mood').value,dislikedIngredients:$('#disliked-ingredients').value.split(',').map(x=>x.trim()).filter(Boolean),favoriteCuisines:[...document.querySelectorAll('[data-cuisine]:checked')].map(x=>x.dataset.cuisine),preferredEffort:$('#memory-easy').checked?'Easy':'Any'}});toast('Your preferences are saved.');render();},
 demo:()=>{draft={mode:'meal',sourceId:'mushroom-toast',prefs:{...defaults},pair:null,adapted:false,confirmed:[]};persist();go('preferences');},
 about:()=>modal(`<p class="eyebrow">Crave Frame</p><h2>Two ways in.<br>One great evening.</h2><p>Start with dinner or a movie or episode. Explore ${meals.length} recipes, search movies and TV through TMDB, and compare explained pairings. Plan together, approve recipe adaptations, and take cooking steps to your phone while the evening plan stays on your larger screen.</p><p>Your saved preferences shape future suggestions. Rescue a planned evening when ingredients, timing, or guest counts change. Pairings use explainable catalog ranking. Watch movies and episodes in your streaming service; Crave Frame plans the evening and provides a viewing timer. Promotional artwork is credited below; manually added titles use illustrative scenery.</p><details class="art-credits"><summary>Featured artwork credits</summary><p>Promotional artwork belongs to its respective rights holders. Source links identify each title; display does not imply endorsement.</p><ul>${shows.filter(s=>artworkFor(s)).map(s=>'<li><a href="'+esc(artworkFor(s).source)+'" target="_blank" rel="noreferrer">'+esc(s.name)+' ↗</a></li>').join('')}</ul></details><p>Food photography is representative. Cuisine and mood connections are interpretations, not claims about food shown on screen. Live catalog metadata: <img src="/app/images/tmdb-logo.svg" alt="TMDB" style="width:110px;height:auto;margin:16px 0"><a href="https://www.themoviedb.org" target="_blank" rel="noreferrer">TMDB</a>. This product uses the TMDB API but is not endorsed or certified by TMDB.</p><p>Use arrow keys and Enter to navigate, or tap on your phone. Escape goes back. Your household access is stored in this browser; clearing browser storage removes your access key.</p>`)
};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled||busy)return;const fn=actions[el.dataset.action];if(!fn)return;try{busy=true;el.setAttribute('aria-busy','true');await fn(el);}catch(error){toast(error.message);}finally{busy=false;el.removeAttribute('aria-busy');}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='meal-diet'){draft.prefs.diet=el.value;recipeLimit=24;persist();render();}if(el.id==='voting-enabled'){draft.votes=el.checked?[{mood:draft.prefs.mood,veto:null},{mood:draft.prefs.mood,veto:null}]:[];persist();render();}if(el.dataset.vote!==undefined){draft.votes[Number(el.dataset.vote)].mood=el.value;draft.votes.forEach(v=>v.veto=null);persist();}if(el.id==='meal-category'){mealCategory=el.value;recipeLimit=24;render();}if(el.id==='meal-cuisine'){mealCuisine=el.value;recipeLimit=24;render();}if(el.id==='meal-time'){mealTime=Number(el.value);recipeLimit=24;render();}if(el.dataset.change==='family'){draft.prefs.family=el.checked;persist();}if(el.dataset.change==='ingredient'){draft.confirmed=el.checked?[...draft.confirmed,el.value]:draft.confirmed.filter(x=>x!==el.value);persist();const focus=el.value;render();[...document.querySelectorAll('[data-change="ingredient"]')].find(x=>x.value===focus)?.focus();}if(['shorter','rememberMood','rememberCuisine','preferEasy'].includes(el.dataset.change))feedback[el.dataset.change]=el.checked;});
document.addEventListener('input',e=>{if(e.target.id==='theme-search'){themeSearch=e.target.value;themeLimit=20;const filtered=movieNights.filter(t=>(t.movie+' '+t.heading+' '+t.mealName).toLowerCase().includes(themeSearch.toLowerCase()));$('#theme-grid').innerHTML=filtered.slice(0,themeLimit).map(themeCard).join('')||'<p>No matching movie nights.</p>';$('#theme-count').textContent=filtered.length+' inspired pairings';$('[data-action=more-themes]').hidden=filtered.length<=themeLimit;}if(e.target.id==='catalog-search'){search=e.target.value;recipeLimit=24;const food=draft.mode==='meal';const filtered=(food?filterMeals(search,mealCategory,mealTime,mealCuisine).filter(m=>dietFits(m,draft.prefs.diet)):shows.filter(s=>draft.prefs.catalog==='Original demo titles'?!s.source&&!s.custom:!!s.source||s.custom)).filter(x=>food||(x.name+' '+(x.genre||x.subtitle)).toLowerCase().includes(search.toLowerCase()));if(food&&$('#recipe-count')){$('#recipe-count').textContent=filtered.length+' of '+meals.length+' recipes';const more=$('[data-action=more-recipes]');if(more)more.hidden=filtered.length<=recipeLimit;}$('#catalog-grid').innerHTML=(food?filtered.slice(0,recipeLimit):filtered).map(x=>food?mealCard(x):showCard(x)).join('')||'<div class="empty"><h2>No matching titles or meals.</h2><p>Try another search.</p></div>';}});
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);void loadRoute().catch(e=>toast(e.message));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#dialog')&&!sharedKey){e.preventDefault();const back={choose:'home',preferences:'choose',results:'preferences',review:'results',cook:'tonight/'+night?.id,feedback:'tonight/'+night?.id};go(back[route()]||'home');return;}if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)||(document.activeElement.matches('input:not([type=checkbox]),select,textarea')))return;
 const root=$('#dialog')||app,items=[...root.querySelectorAll('button:not(:disabled),a,input,select,summary')].filter(x=>x.getClientRects().length);const current=document.activeElement;if(!items.includes(current)){items[0]?.focus();e.preventDefault();return;}const a=current.getBoundingClientRect(),horizontal=['ArrowLeft','ArrowRight'].includes(e.key),sign=['ArrowRight','ArrowDown'].includes(e.key)?1:-1;let best=null,bestScore=Infinity;for(const item of items){if(item===current)continue;const b=item.getBoundingClientRect(),dx=(b.left+b.width/2)-(a.left+a.width/2),dy=(b.top+b.height/2)-(a.top+a.height/2),forward=(horizontal?dx:dy)*sign,cross=Math.abs(horizontal?dy:dx);if(forward>5){const score=forward+cross*3;if(score<bestScore){best=item;bestScore=score;}}}if(best){e.preventDefault();best.focus();best.scrollIntoView({block:'nearest',inline:'nearest'});}});
setInterval(updateClocks,1000);
setInterval(async()=>{if(polling||busy||document.hidden||!night||!['phone','tonight','cook'].includes(route()))return;polling=true;try{const updated=await api(sharedKey?'shared/'+sharedKey:'nights/'+night.id);if(updated.step!==night.step||updated.status!==night.status||updated.timer!==night.timer||updated.watchStarted!==night.watchStarted||updated.mealId!==night.mealId||updated.showId!==night.showId||updated.prefs.people!==night.prefs.people||updated.adapted!==night.adapted||updated.planStart!==night.planStart||updated.dinnerMinutes!==night.dinnerMinutes){night=updated;render();}}catch{}finally{polling=false;}},5000);
void load();


setInterval(()=>{if(sharedKey&&night&&!document.hidden)api('shared/'+sharedKey+'/connect','POST',{}).catch(()=>{});},30000);
